import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_INT = Integer.MAX_VALUE;

    static class Edge {
        int v, p, capacity, weight;
        Edge(int v, int p, int capacity, int weight) {
            this.v = v;
            this.p = p;
            this.capacity = capacity;
            this.weight = weight;
        }
    }

    static class FlowImplementation {
        static final int MAX_NODES = 10001;
        static List<Edge>[] graph = new ArrayList[MAX_NODES];
        static int[] visited = new int[MAX_NODES];
        static int[] current = new int[MAX_NODES];
        static int totalNodes;
        static int[] dist = new int[MAX_NODES];
        static int[] potential = new int[MAX_NODES];

        static {
            for (int i = 0; i < MAX_NODES; i++) {
                graph[i] = new ArrayList<>();
            }
        }

        static int createVertices(int count) {
            int start = totalNodes;
            for (int i = 0; i < count; i++) {
                graph[totalNodes++].clear();
            }
            return start;
        }

        static void addEdge(int u, int v, int cap, int w) {
            graph[u].add(new Edge(v, graph[v].size(), cap, w));
            graph[v].add(new Edge(u, graph[u].size() - 1, 0, -w));
        }

        static boolean findShortestPath(int s, int t) {
            Arrays.fill(dist, 0, totalNodes, MAX_INT);
            Arrays.fill(visited, 0, totalNodes, 0);
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            dist[s] = 0;
            pq.offer(new int[]{0, s});
            while (!pq.isEmpty()) {
                int[] du = pq.poll();
                int u = du[1], duDist = du[0];
                if (visited[u] != 0) continue;
                visited[u] = 1;
                for (Edge e : graph[u]) {
                    int v = e.v;
                    int dv = duDist + potential[u] + e.weight - potential[v];
                    if (e.capacity == 0 || visited[v] != 0 || dist[v] <= dv) continue;
                    dist[v] = dv;
                    pq.offer(new int[]{dist[v], v});
                }
            }
            return visited[t] != 0;
        }

        static boolean buildLevelGraph(int s, int t) {
            Arrays.fill(visited, 0, totalNodes, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            visited[s] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (Edge e : graph[u]) {
                    int v = e.v;
                    if (visited[v] != 0 || e.capacity == 0) continue;
                    if (dist[v] != dist[u] + e.weight - potential[v] + potential[u]) continue;
                    visited[v] = visited[u] + 1;
                    q.offer(v);
                }
            }
            return visited[t] != 0;
        }

        static int sendFlow(int u, int t, int flow) {
            if (u == t) return flow;
            int totalSent = 0;
            for (int i = current[u]; i < graph[u].size(); i++) {
                Edge e = graph[u].get(i);
                int v = e.v;
                if (e.capacity == 0 || visited[v] != visited[u] + 1) continue;
                if (dist[v] != dist[u] + e.weight - potential[v] + potential[u]) continue;
                int pushed = sendFlow(v, t, Math.min(e.capacity, flow));
                totalSent += pushed;
                flow -= pushed;
                e.capacity -= pushed;
                graph[v].get(e.p).capacity += pushed;
                if (flow == 0) break;
            }
            return totalSent;
        }

        static int[] computeFlowCost(int s, int t, int maxFlow) {
            int totalFlow = 0, totalCost = 0;
            Arrays.fill(potential, 0, totalNodes, 0);
            while (findShortestPath(s, t)) {
                int flow = 0;
                while (buildLevelGraph(s, t)) {
                    Arrays.fill(current, 0, totalNodes, 0);
                    int pushedFlow = sendFlow(s, t, maxFlow);
                    maxFlow -= pushedFlow;
                    flow += pushedFlow;
                    if (maxFlow == 0) break;
                }
                totalFlow += flow;
                totalCost += (dist[t] + potential[t]) * flow;
                for (int i = 0; i < totalNodes; i++) {
                    potential[i] += dist[i];
                }
                if (maxFlow == 0) break;
            }
            return new int[]{totalFlow, totalCost};
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        int totalVertices = Math.max(n, k) * 2;
        int baseVertexIndex = FlowImplementation.createVertices(totalVertices * n);
        int s = FlowImplementation.createVertices(1);
        int t = FlowImplementation.createVertices(1);

        for (int j = 0; j < k; j++) {
            int a = Integer.parseInt(br.readLine());
            a--;
            FlowImplementation.addEdge(s, a, 1, 0);
        }

        for (int z = 1; z <= m; z++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken()) - 1;
            int v = Integer.parseInt(st.nextToken()) - 1;
            for (int i = 0; i + 1 < totalVertices; i++) {
                int u1 = u + i * n;
                int v1 = v + (i + 1) * n;
                int u2 = u + (i + 1) * n;
                int v2 = v + i * n;
                for (int j = 0; j < k; j++) {
                    int cost = c + d * (2 * j + 1);
                    FlowImplementation.addEdge(u1, v1, 1, cost);
                    FlowImplementation.addEdge(v2, u2, 1, cost);
                }
            }
        }

        for (int i = 0; i + 1 < totalVertices; i++) {
            for (int j = 0; j < n; j++) {
                int u = j + i * n;
                int v = j + (i + 1) * n;
                FlowImplementation.addEdge(u, v, MAX_INT, c);
            }
        }

        for (int i = 0; i < totalVertices; i++) {
            FlowImplementation.addEdge(i * n, t, MAX_INT, 0);
        }

        int[] result = FlowImplementation.computeFlowCost(s, t, MAX_INT);
        System.out.println(result[1]);
    }
}

